const INFLUENCE = 120;
const BASE_ICON_SIZE = 48;

function onMove(e: MouseEvent) {
  if (maxScale <= 1) { resetIcons(); return; }

  const scale = parseFloat(
    dock.style.getPropertyValue('--dock-scale') || '1'
  );
  const baseSize = BASE_ICON_SIZE * scale;

  for (let i = 0; i < icons.length; i++) {
    const rect = slots[i].getBoundingClientRect();
    const center = rect.left + rect.width / 2;
    const dist = Math.abs(e.clientX - center);

    // Quadratic falloff — smooth Gaussian-like curve
    const factor = Math.max(0, 1 - (dist / INFLUENCE) ** 2);
    const s = 1 + (maxScale - 1) * factor;
    const size = Math.round(baseSize * s);

    icons[i].style.width = size + 'px';
    icons[i].style.height = size + 'px';
    icons[i].style.transform =
      `translateY(${-Math.round((size - baseSize) * 0.5)}px)`;
  }
}

interface FSNode {
  type: 'file' | 'dir';
  name: string;
  children?: FSNode[];
  content?: string;
}

function buildFS(data: ProfileData): FSNode {
  const root: FSNode = { type: 'dir', name: '~', children: [] };

  root.children!.push({
    type: 'file', name: 'about.txt',
    content: `${data.about.role}\n${data.about.bio.join('\n\n')}`
  });

  const projDir: FSNode = { type: 'dir', name: 'projects', children: [] };
  for (const p of data.projects.items) {
    projDir.children!.push({
      type: 'file', name: `${slugify(p.name)}.md`,
      content: `# ${p.name}\n\n${p.description}\nTags: ${p.tags.join(', ')}`
    });
  }
  root.children!.push(projDir);
  return root;
}

function resolvePath(path: string): string {
  if (path === '/' || path === '~') return '~';
  if (path.startsWith('~/'))
    return normParts(['~', ...path.slice(2).split('/')]);
  const base = state.cwd === '~' ? ['~'] : state.cwd.split('/');
  return normParts([...base, ...path.split('/')]);
}

function normParts(parts: string[]): string {
  const result: string[] = ['~'];
  for (const seg of parts.slice(1)) {
    if (seg === '.' || seg === '') continue;
    if (seg === '..') { if (result.length > 1) result.pop(); }
    else result.push(seg);
  }
  return result.join('/');
}

type AchievementEvent = 'window-opened' | 'terminal-command' | ...;

interface AchievementDef {
  id: string;
  event: AchievementEvent;
  threshold: number;
  trackUnique?: boolean;
}

// O(1) event lookup — pre-built at module load
const EVENT_MAP = new Map<AchievementEvent, AchievementDef[]>();
for (const a of ACHIEVEMENTS) {
  const list = EVENT_MAP.get(a.event) || [];
  list.push(a);
  EVENT_MAP.set(a.event, list);
}

// Runtime Sets for O(1) unique tracking
const uniqueSets = new Map<string, Set<string>>();

function track(event: AchievementEvent, payload?: { id?: string }) {
  ensureInit(); // lazy load from localStorage

  const matching = EVENT_MAP.get(event);
  if (!matching) return;

  let dirty = false;

  for (const def of matching) {
    const state = store.states[def.id];
    if (!state || state.unlocked) continue;

    if (def.trackUnique) {
      let set = uniqueSets.get(def.id);
      if (!set) { set = new Set(); uniqueSets.set(def.id, set); }
      const uid = payload?.id ?? '';
      if (uid && !set.has(uid)) {
        set.add(uid);
        state.progress = set.size;
        dirty = true;
      }
    } else {
      state.progress++;
      dirty = true;
    }

    if (state.progress >= def.threshold) {
      state.unlocked = true;
      state.unlockedAt = new Date().toISOString();
      notifyUnlock(def);
    }
  }

  if (dirty) save(); // single save per batch
}

let pendingExit = false;
let startMouseX = 0;
let startMouseY = 0;

const onMouseMove = (e: MouseEvent) => {
  if (!dragging) return;

  if (pendingExit) {
    const dx = Math.abs(e.clientX - startMouseX);
    const dy = Math.abs(e.clientY - startMouseY);
    if (dx < 3 && dy < 3) return; // ignore micro-movements

    const state = windowStates.get(win.id);
    if (state) {
      // Restore previous window size
      const prevW = state.fullscreen
        ? parseFloat(state.preFullWidth) || win.offsetWidth * 0.6
        : parseFloat(state.preZoomWidth) || win.offsetWidth * 0.6;
      const prevH = state.fullscreen
        ? parseFloat(state.preFullHeight) || win.offsetHeight * 0.6
        : parseFloat(state.preZoomHeight) || win.offsetHeight * 0.6;

      if (state.fullscreen) {
        state.fullscreen = false;
        win.classList.remove('os-window--fullscreen');
      }
      state.zoomed = false;

      // Center window under cursor
      win.style.transition = 'none';
      win.style.left =
        `${Math.max(8, e.clientX - prevW / 2)}px`;
      win.style.top =
        `${Math.max(32, e.clientY - 20)}px`;
      win.style.width = `${prevW}px`;
      win.style.height = `${prevH}px`;

      offsetX = e.clientX - win.offsetLeft;
      offsetY = e.clientY - win.offsetTop;
    }
    pendingExit = false;
    return;
  }

  // Normal drag — clamp to desktop bounds
  const x = Math.max(8, Math.min(e.clientX - offsetX, dw - ww - 8));
  const y = Math.max(32, Math.min(e.clientY - offsetY, dh - wh - 8));
  win.style.left = `${x}px`;
  win.style.top = `${y}px`;
};

public enum DependencyScope {
    case singleton  // Shared globally
    case transient  // New instance each time
    case scoped     // Singleton within a child container
    case weak       // Singleton with weak reference
}

final class ServiceRegistration<T>: @unchecked Sendable {
    private var cachedInstance: T?
    private weak var weakInstance: AnyObject?
    private var inflightTask: Task<T, any Error>?
    private let lock = NSLock()

    // Fast path: return cached without Task allocation
    private func getCachedInstance() -> T? {
        lock.lock()
        defer { lock.unlock() }
        if let cached = cachedInstance { return cached }
        if scope == .weak, let cached = weakInstance as? T { return cached }
        return nil
    }

    // Task coalescing: reuse inflight task for concurrent resolves
    private func getOrCreateInflightTask(
        resolver: Resolver
    ) -> Task<T, any Error> {
        lock.lock()
        defer { lock.unlock() }
        if let cached = cachedInstance { return Task { cached } }
        if let task = inflightTask { return task }

        let task = Task<T, any Error> { [self] in
            try await self.invokeFactory(using: resolver)
        }
        inflightTask = task
        return task
    }

    private func finalizeCachedInstance(_ instance: T) -> T {
        lock.lock()
        defer { lock.unlock() }
        inflightTask = nil
        if let cached = cachedInstance { return cached }
        cachedInstance = instance
        return instance
    }
}

final class KeychainStorage: StorageProtocol {
    private let service: String

    init(service: String = Bundle.main.bundleIdentifier
        ?? String(describing: KeychainStorage.self)) {
        self.service = service
    }

    func save<T: Codable>(_ value: T, for key: String) throws {
        let data = try JSONEncoder().encode(value)

        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: key,
        ]
        let attributes: [String: Any] = [
            kSecValueData as String: data,
        ]

        // Update-or-insert pattern
        let status = SecItemUpdate(
            query as CFDictionary, attributes as CFDictionary
        )
        if status == errSecItemNotFound {
            let insertQuery = query.merging(attributes) { $1 }
            let insertStatus = SecItemAdd(
                insertQuery as CFDictionary, nil
            )
            guard insertStatus == errSecSuccess else {
                throw mapStatus(insertStatus)
            }
        } else if status != errSecSuccess {
            throw mapStatus(status)
        }
    }

    func read<T: Codable>(_ type: T.Type, for key: String) throws -> T {
        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: key,
            kSecReturnData as String: true,
            kSecMatchLimit as String: kSecMatchLimitOne,
        ]
        var item: AnyObject?
        let status = SecItemCopyMatching(
            query as CFDictionary, &item
        )
        guard status == errSecSuccess,
              let data = item as? Data else {
            throw mapStatus(status)
        }
        return try JSONDecoder().decode(T.self, from: data)
    }
}

@MainActor
final class EventChannel<Payload>: AnyEventChannel {
    private var continuations:
        [UUID: AsyncStream<Payload>.Continuation] = [:]
    private let sticky: Bool
    private var lastValue: Payload?

    init(sticky: Bool = false) {
        self.sticky = sticky
    }

    func subscribe() -> AsyncStream<Payload> {
        let id = UUID()
        let cachedValue = sticky ? lastValue : nil

        return AsyncStream { continuation in
            // Replay cached value for sticky channels
            if let cachedValue {
                continuation.yield(cachedValue)
            }
            self.continuations[id] = continuation

            continuation.onTermination = { @Sendable _ in
                Task { @MainActor in
                    self.continuations.removeValue(forKey: id)
                }
            }
        }
    }

    func send(_ payload: Payload) {
        if sticky { lastValue = payload }
        for continuation in continuations.values {
            continuation.yield(payload)
        }
    }

    func finish() {
        for continuation in continuations.values {
            continuation.finish()
        }
        continuations.removeAll()
        lastValue = nil
    }
}

