class CertificatePinningManager {
    typealias HostEvaluation = (SecTrust) -> Bool
    private(set) var hostEvaluations:
        [String: HostEvaluation] = [:]

    func fetchCertificates(
        withExtensions exts: Set<String>,
        in bundle: Bundle
    ) -> Set<Data> {
        var certs: Set<Data> = []
        for ext in exts {
            let urls = bundle.urls(
                forResourcesWithExtension: ext,
                subdirectory: nil
            ) ?? []
            for url in urls {
                guard let data = try? Data(contentsOf: url)
                else { continue }
                certs.insert(data)
            }
        }
        return certs
    }

    func register(
        evaluation: @escaping HostEvaluation,
        for host: String
    ) {
        hostEvaluations[host] = evaluation
    }
}

// URLSessionDelegate integration
extension CertificatePinningManager {
    func urlSession(
        _ session: URLSession,
        didReceive challenge: URLAuthenticationChallenge,
        completionHandler: @escaping
            (URLSession.AuthChallengeDisposition,
             URLCredential?) -> Void
    ) {
        guard challenge.protectionSpace
            .authenticationMethod ==
            NSURLAuthenticationMethodServerTrust
        else {
            completionHandler(.performDefaultHandling, nil)
            return
        }
        let host = challenge.protectionSpace.host
        guard let evaluation = hostEvaluations[host],
              let trust = challenge.protectionSpace.serverTrust,
              evaluation(trust)
        else {
            completionHandler(.cancelAuthenticationChallenge, nil)
            return
        }
        completionHandler(
            .useCredential, URLCredential(trust: trust)
        )
    }
}

protocol AppSecurityServicing: AnyObject {
    var lockState: AnyPublisher<AppSecurity.LockState, Never> { get }
    var state: AppSecurity.LockState { get }
    func unlock()
    func userInteraction()
    func lock()
}

final class AppSecurity: AppSecurityServicing {
    enum LockState: Equatable {
        case unlocked
        case warning(TimeInterval)
        case locked
    }

    private let lockStateSubject =
        CurrentValueSubject<LockState, Never>(.locked)
    var lockState: AnyPublisher<LockState, Never> {
        lockStateSubject.receive(on: DispatchQueue.main)
            .eraseToAnyPublisher()
    }
    private var timer: Timer?
    private let warningTimeout: TimeInterval = 5
    private let lockTimeout: TimeInterval = 5 * 60

    var state: LockState { lockStateSubject.value }

    func unlock() { startInactivityTimer() }

    func userInteraction() {
        guard state != .locked else { return }
        startInactivityTimer()
    }

    func lock() {
        guard state != .locked else { return }
        lockStateSubject.send(.locked)
        stopTimer()
    }

    private func startInactivityTimer() {
        stopTimer()
        lockStateSubject.send(.unlocked)
        timer = Timer.scheduledTimer(
            withTimeInterval: lockTimeout - warningTimeout,
            repeats: false
        ) { [weak self] _ in
            self?.startCountdown()
        }
    }

    private func startCountdown() {
        stopTimer()
        var seconds = warningTimeout
        lockStateSubject.send(.warning(seconds))
        timer = Timer.scheduledTimer(
            withTimeInterval: 1, repeats: true
        ) { [weak self] _ in
            seconds -= 1
            self?.lockStateSubject.send(.warning(seconds))
        }
    }

    private func stopTimer() {
        timer?.invalidate()
        timer = nil
    }
}

import CryptoKit
import Foundation

public enum Crypto {
    public static func getSymmetricKey(pass: String?) -> SymmetricKey? {
        guard let pass, let data = pass.data(using: .utf8)
        else { return nil }
        return SymmetricKey(data: SHA256.hash(data: data))
    }

    public static func signatureHMAC<T: Encodable>(
        _ value: T, pass: String?
    ) -> String? {
        guard let key = getSymmetricKey(pass: pass),
              let data = value.encode
        else { return nil }
        return Data(
            HMAC<SHA512>.authenticationCode(for: data, using: key)
        ).base64EncodedString().urlEncoded
    }

    public static func createSealedBox<T: Encodable>(
        _ value: T, pass: String?
    ) -> Data? {
        guard let key = getSymmetricKey(pass: pass),
              let data = value.encode
        else { return nil }
        guard let sealedBox = try? AES.GCM.seal(
            data, using: key, nonce: AES.GCM.Nonce()
        ) else { return nil }
        return sealedBox.combined
    }

    public static func openSealedBox<T: Decodable>(
        _ sealedBox: Data?, pass: String?
    ) -> T? {
        guard let data = sealedBox,
              let key = getSymmetricKey(pass: pass),
              let box = try? AES.GCM.SealedBox(combined: data),
              let decrypted = try? AES.GCM.open(box, using: key)
        else { return nil }
        return T(from: decrypted)
    }
}

open class Validator {
    private var next: Validator?
    private let failText: String

    public init(failText: String, next: Validator?) {
        self.next = next
        self.failText = failText
    }

    public func failed() -> String? { failText }

    open func validate(_ text: String) -> String? {
        next?.validate(text)
    }

    // Static factory methods — composable chain
    public static func maxLength(
        max: Int, failText: String = "MaxLength",
        next: Validator? = nil
    ) -> Validator {
        LengthValidator(
            length: max, compareOptions: .greaterEqual,
            failText: failText, next: next
        )
    }

    public static func minLength(
        min: Int, failText: String = "MinLength",
        next: Validator? = nil
    ) -> Validator {
        LengthValidator(
            length: min, compareOptions: .lessEqual,
            failText: failText, next: next
        )
    }

    public static func regex(
        regex: String, failText: String = "Regex",
        next: Validator? = nil
    ) -> Validator {
        SearchValidator(
            text: regex, compareOptions: .regularExpression,
            rangeOptions: .equal, failText: failText, next: next
        )
    }

    public static func email(
        failText: String = "Email", next: Validator? = nil
    ) -> Validator {
        .regex(
            regex: "^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+"
                + "@[a-zA-Z0-9-]+(?:\\.[a-zA-Z0-9-]+)*$",
            failText: failText, next: next
        )
    }
}

