open class TokenInterceptor: RequestInterceptor {
    private var isRefreshing = false
    private let lock = NSLock()

    public func adapt(
        _ urlRequest: URLRequest,
        for session: Session,
        completion: @escaping (Result<URLRequest, Error>) -> Void
    ) {
        var adapted = urlRequest
        if let token = getToken() {
            createHeader(token: token).forEach {
                adapted.addValue($0.value, forHTTPHeaderField: $0.name)
            }
        }
        completion(.success(adapted))
    }

    public func retry(
        _ request: Request, for session: Session,
        dueTo error: Error,
        completion: @escaping (RetryResult) -> Void
    ) {
        lock.lock(); defer { lock.unlock() }

        if isRefreshing {
            isRefreshing = false
            if conditionToRefresh(
                request, for: session,
                dueTo: error, token: getToken()
            ) {
                refreshToken { [weak self] result in
                    switch result {
                    case let .success(token):
                        self?.saveToken(token)
                        completion(.retry)
                    case .failure:
                        completion(.doNotRetry)
                    }
                }
            } else {
                completion(.doNotRetry)
            }
        } else {
            isRefreshing = true
            completion(.doNotRetry)
        }
    }

    // Template method hooks — override in subclass
    open func getToken() -> TokenProtocol? { nil }
    open func saveToken(_ token: TokenProtocol) {}
    open func refreshToken(
        _ completion: @escaping (Result<TokenProtocol, Error>) -> Void
    ) {}
    open func conditionToRefresh(
        _ request: Request, for session: Session,
        dueTo error: Error, token: TokenProtocol?
    ) -> Bool { false }
    open func createHeader(token: TokenProtocol) -> [HTTPHeader] {
        [.authorization(bearerToken: token.accessToken)]
    }
}
